## Code Example
```javascript
function maxIntervalValue(A, B, k) {
  const n = A.length;
  const PA = [0], PB = [0];
  for (let i = 1; i <= n; i++) {
    PA[i] = PA[i-1] + A[i-1];
    PB[i] = PB[i-1] + B[i-1];
  }
  const dp = Array(n+1).fill(null).map(() => Array(k+1).fill(-Infinity));
  const prev = Array(n+1).fill(null).map(() => Array(k+1).fill(null));
  dp[0][0] = 0;
  for (let r = 1; r <= n; r++) {
    for (let t = 1; t <= k; t++) {
      for (let l = 1; l <= r; l++) {
        const val = (PA[r] - PA[l-1]) * (PB[r] - PB[l-1]);
        const candidate = dp[l-1][t-1] + val;
        if (candidate > dp[r][t]) {
          dp[r][t] = candidate;
          prev[r][t] = { l, r: l-1 };
        }
      }
    }
  }
  return dp[n][k];
}
```

## Why This Is Asked
Tests a novel fixed-gap non-crossing pairing constraint, a natural extension of classic non-crossing matching problems, while probing DP state design and reconstruction.

## Key Concepts
- DP over prefixes with fixed pair distance
- Non-crossing/disjoint constraint handling
- Backpointers for reconstruction
- Space/time optimization trade-offs

## Code Example
```javascript
function maxFixedGapPairs(A, d, k) {
  const n = A.length;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const take = Array.from({ length: n + 1 }, () => Array(k + 1).fill(false));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      dp[i][t] = dp[i - 1][t];
      if (t > 0 && i - d - 1 >= 0) {
        const cand = dp[i - d - 1][t - 1] + A[i - 1] * A[i - d - 1];
        if (cand > dp[i][t]) {
          dp[i][t] = cand;
          take[i][t] = true;
        }
      }
    }
  }
  const pairs = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    if (take[i][t]) {
      pairs.push([i - d, i]); // 1-based indices of the pair
      i = i - d - 1;
      t--;
    } else {
      i--;
    }
  }
  pairs.reverse();
  return { value: dp[n][k], pairs };
}
